<section class="page-hero"><p class="eyebrow">OUR AUTHORS</p><h1>Voices worth <em>returning to.</em></h1><p>Explore the original writers whose work finds a home at Archon.</p></section><section class="section"><form class="author-search" method="get"><label class="sr-only" for="author-search">Search authors</label><input id="author-search" name="q" value="<?=Security::e($q)?>" placeholder="Search authors"><button class="button outline">Search</button></form><div class="author-grid"><?php foreach($authors as $author):?><a class="author-card" href="/authors/<?=Security::e($author['slug'])?>"><div class="portrait"><?=Security::e(mb_substr($author['name'],0,1))?></div><h2><?=Security::e($author['name'])?></h2><p><?=Security::e($author['tagline']??'Archon author')?></p></a><?php endforeach;?></div><?php if(!$authors):?><div class="empty"><h2>No author found</h2><p>Try a different name or browse the full list.</p><a class="button" href="/authors">View all authors</a></div><?php endif;?></section>
